<template>
	<view class="searchLayout">
		<view class="search">
			<uni-search-bar 
			@confirm="onSearch"
			@cancel="onClear"
			@clear="onClear"
			focus 
			placeholder="搜索"
			v-model="queryParams.content">
			</uni-search-bar>
		</view>
		
		
		<view>
			<view class="history" v-if="historySearch.length">
				<view class="topTitle">
					<view class="text">最近搜索</view>
					<view class="icon" @click="removeHistory">
						<uni-icons type="trash" size="25"></uni-icons>
					</view>
				</view>
				<view class="tabs">
					<view class="tab" v-for="tab in historySearch" :key="tab" @click="clickTab(tab)">{{tab}}</view>		
				</view>
			</view>
			
			<view class="recommend">
				<view class="topTitle">
					<view class="text">热门搜索</view>				
				</view>
				<view class="tabs">				
					<view class="tab" v-for="tab in recommendList" :key="tab" @click="clickTab(tab)">{{tab}}</view>
				</view>
			</view>
		</view>
		
		
		<view class="noSearch">
			<!-- <uv-empty mode="search" icon="http://cdn.uviewui.com/uview/empty/search.png"></uv-empty> -->
			<text>没有搜索内容</text>
		</view>
		
	<!-- 帖子列表 -->
	    <scroll-view class="post-list" scroll-y="true">
	      <view class="post-item" v-for="(post, index) in TreeHolePostList" :key="index">
	        <!-- 帖子头部 -->
	        <view class="post-header">
	          <image class="user-avatar" :src="post.avatar" mode="aspectFill"></image>
	          <view class="user-info">
	            <view class="user-name">{{ post.userName }}</view>
	            <view class="post-meta">
	              <view class="post-category">{{ post.postClass }}</view>
	              <view class="post-time">{{ formatPostTimeSimple(post.createTime) }}</view>
	            </view>
	          </view>
	        </view>
	
	        <!-- 帖子内容 -->
	        <view class="post-content">
	          <text class="content-text">{{ post.content }}</text>
	          <view class="post-images" v-if="post.images && post.images.length">
	            <image 
	              v-for="(img, imgIndex) in post.images" 
	              :key="imgIndex"
	              class="content-image"
	              :src="img"
	              mode="aspectFill"
	              @tap="previewImage(post.images, imgIndex)"
	            ></image>
	          </view>
	        </view>
	
	        <!-- 帖子底部操作栏 -->
	        <view class="post-actions">
	          <view class="action-item" @tap="handleShare(post)">
	            <image class="action-icon" src="/static/share.png"></image>
	            <text class="action-text">分享</text>
	          </view>
	          <view class="action-item" @tap="handleComment(post)">
	            <image class="action-icon" src="/static/comment.png"></image>
	            <text class="action-text">{{ post.commentCount }}</text>
	          </view>
	          <view class="action-item" @tap="handleLike(post.id, post.likeStatus)">
	            <image 
	              class="action-icon" 
	              :src="post.likeStatus ? '/static/icons/like-i.png' : '/static/icons/like-o.png'"
	            ></image>
	            <text class="action-text" :class="{ liked: post.likeStatus }">
	              {{ post.likeCount }}
	            </text>
	          </view>
	        </view>
	      </view>
		  
		  
	      <!-- 加载更多 -->
	<!--     <view class="load-more">
	        <text>加载更多</text>
	      </view> -->
	<!--      <view class="no-more" v-else>
	        <text>没有更多了</text>
	      </view> -->
	    </scroll-view>
		
		<view class="loadingLayout" v-if="TreeHolePostList.length || noData">
			<uni-load-more :status="noData?'noMore':'loading'"></uni-load-more>
		</view>
		
		
	</view>
</template>

<script setup>
import {ref} from "vue";
import {onLoad,onUnload,onReachBottom} from "@dcloudio/uni-app";
import { apiGetTreeHolePost, apiTreeHoldPostLike } from '../../api/treehole'

//查询参数
const queryParams = ref({	
	page:1,
	pageSize:10,
	content:""
})

const searchData = async () =>{
	let res = await apiGetTreeHolePost(queryParams.value)
	TreeHolePostList.value = res.data
	console.log(res);
}

//搜索历史词
const historySearch = ref(uni.getStorageSync("historySearch") || []);

//热门搜索词
const recommendList = ref(["美女","帅哥","宠物","卡通"]);

//没有更多
const noData = ref(false);
//没有搜索结果
const noSearch = ref(false);

//搜索结果列表
const TreeHolePostList = ref([]);


//点击搜索
const onSearch = ()=>{
	historySearch.value = [...new Set([queryParams.value.content,...historySearch.value])]
	uni.setStorageSync("historySearch", historySearch.value)
	searchData()
}

//点击清除按钮
const onClear = ()=>{
	
}



//点击标签进行搜索
const clickTab = (value)=>{
	queryParams.value.content = value;
}


//点击清空搜索记录
const removeHistory = ()=>{
	uni.showModal({
		title:"是否清空历史搜索？",
		success:res=>{
			if(res.confirm){
				uni.removeStorageSync("historySearch")
				historySearch.value = []
			}
		}
	})
}

//触底加载更多
onReachBottom(()=>{
	
})

//关闭有页面
onUnload(()=>{
	
})


const formatPostTimeSimple = (timeArray) => {
	  if (!timeArray || timeArray.length !== 6) {
	    return '时间错误'
	  }
	  
	  const [year, month, day, hour, minute, second] = timeArray
	  const postDate = new Date(year, month - 1, day, hour, minute, second)
	  const now = new Date()
	  const diffMs = now - postDate
	  
	  const diffSeconds = Math.floor(diffMs / 1000)
	  const diffMinutes = Math.floor(diffMs / (1000 * 60))
	  const diffHours = Math.floor(diffMs / (1000 * 60 * 60))
	  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24))
	  
	  // 使用中文时间描述
	  if (diffSeconds < 60) {
	    return '刚刚'
	  } else if (diffMinutes < 60) {
	    return `${diffMinutes}分钟前`
	  } else if (diffHours < 24) {
	    return `${diffHours}小时前`
	  } else if (diffDays === 1) {
	    return '昨天'
	  } else if (diffDays === 2) {
	    return '前天'
	  } else if (diffDays <= 3) {
	    return `${diffDays}天前`
	  } else {
	    // 超过3天显示具体日期
	    const formattedMonth = String(month).padStart(2, '0')
	    const formattedDay = String(day).padStart(2, '0')
	    const formattedHour = String(hour).padStart(2, '0')
	    const formattedMinute = String(minute).padStart(2, '0')
	    
	    // 同一年只显示月日，不同年显示年月日
	    if (now.getFullYear() === year) {
	      return `${formattedMonth}-${formattedDay} ${formattedHour}:${formattedMinute}`
	    } else {
	      return `${year}-${formattedMonth}-${formattedDay} ${formattedHour}:${formattedMinute}`
	    }
	  }
	}
</script>

<style lang="scss" scoped>
@import "../../common/style/treehole.scss";
